import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"新增配置项：放对模块并接入正确加载流程","description":"判断新设置应属于 Core、API、Worker 还是 MCP，并完成默认值、校验、运行时覆盖和测试。","frontmatter":{"page_id":"development-configuration","title":"新增配置项：放对模块并接入正确加载流程","description":"判断新设置应属于 Core、API、Worker 还是 MCP，并完成默认值、校验、运行时覆盖和测试。"},"headers":[],"relativePath":"development/configuration.md","filePath":"development/configuration.md","lastUpdated":1786627803000}'),o={name:"development/configuration.md"};function r(l,e,d,n,c,h){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="新增配置项-放对模块并接入正确加载流程" tabindex="-1">新增配置项：放对模块并接入正确加载流程 <a class="header-anchor" href="#新增配置项-放对模块并接入正确加载流程" aria-label="Permalink to &quot;新增配置项：放对模块并接入正确加载流程&quot;">​</a></h1><p>新增配置时，先处理归属和生效方式。一个放错模块的设置会制造反向依赖；一个只登记、不从有效设置入口读取的运行时设置，会在管理页面显示成功，却不改变实际行为。</p><h2 id="先决定由哪个模块拥有" tabindex="-1">先决定由哪个模块拥有 <a class="header-anchor" href="#先决定由哪个模块拥有" aria-label="Permalink to &quot;先决定由哪个模块拥有&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置用途</th><th>应放位置</th><th>当前例子</th></tr></thead><tbody><tr><td>多个后端模块共享的数据库、Milvus、仓库、安全基础设置</td><td>Core 的 <code>Settings</code></td><td><code>DATABASE_URL</code>、<code>REPOSITORY_STORAGE_PATH</code>、<code>ENCRYPTION_KEY</code></td></tr><tr><td>HTTP、浏览器 Cookie、登录限流、访问令牌、API 轮询器</td><td>API 的 <code>ApiSettings</code></td><td><code>REDIS_URL</code>、<code>CORS_ORIGINS</code>、<code>POLLER_INTERVAL_SECONDS</code></td></tr><tr><td>分析队列、并发、LSP、依赖准备和提问策略</td><td>Worker 的 <code>WorkerSettings</code></td><td><code>MAX_PARALLEL_REPOSITORY_RUNS</code>、<code>REPOSITORY_LSP_ENABLED</code></td></tr><tr><td>MCP 监听地址、来源、主机和构建身份</td><td>MCP 的 <code>McpSettings</code></td><td><code>MCP_ALLOWED_HOSTS</code>、<code>MCP_BUILD_COMMIT</code></td></tr><tr><td>前端构建时地址与网页行为</td><td>Frontend 的构建配置</td><td>API 基础地址和前端构建选项</td></tr></tbody></table><p>Core 不能因为“其他模块也能导入它”就收纳所有设置。它明确不拥有 Redis、Cookie、访问令牌、Worker 分析策略或 MCP 输出行为。API 也不能依赖 Worker 或 MCP 源码。</p><p>Worker 的在线管理契约是一个特殊边界：37 项 Worker 定义放在 Core 的 <code>worker_runtime_contract.py</code>，让 API 可以展示和校验它们；字段和实际消费仍在 Worker。契约共享不等于把 Worker 行为搬进 Core。</p><h2 id="再决定是否允许在线覆盖" tabindex="-1">再决定是否允许在线覆盖 <a class="header-anchor" href="#再决定是否允许在线覆盖" aria-label="Permalink to &quot;再决定是否允许在线覆盖&quot;">​</a></h2><p>只有满足下面条件的设置才适合进入数据库运行时设置：</p><ul><li>改动只影响后续操作，不要求重建数据库连接、HTTP 监听器或加密身份；</li><li>多实例可以在短暂刷新延迟内逐步采用新值；</li><li>可以用明确类型、范围和生效说明避免歧义；</li><li>恢复环境值时，只需删除数据库覆盖，不需要迁移已有数据。</li></ul><p>密钥、数据库地址、Redis 地址、Cookie 名称、监听地址和生产身份不适合在线改动。当前 API 进程只有 11 项可在线覆盖设置；系统管理接口显示的另外 37 项由 Worker 消费。</p><h2 id="当前加载流程" tabindex="-1">当前加载流程 <a class="header-anchor" href="#当前加载流程" aria-label="Permalink to &quot;当前加载流程&quot;">​</a></h2><ol><li>Core <code>Settings</code> 声明共享字段，并读取默认值、<code>.env</code> 和进程环境。</li><li>API、Worker 与 MCP 通过继承增加本模块字段。</li><li><code>get_settings()</code>、<code>get_api_settings()</code> 等入口在进程内缓存设置对象。</li><li>各服务在启动时运行自己的校验函数。</li><li>API 或 Worker 从 <code>SystemSetting</code> 表读取已登记的 <code>runtime.&lt;name&gt;</code> 行，校验并放入进程内覆盖表。</li><li>实际业务代码通过 <code>get_effective_settings()</code> 或 <code>get_effective_api_settings()</code> 读取“启动值加运行时覆盖”的结果。</li></ol><p>第 6 步不能省略。若业务代码继续调用基础的缓存设置入口，数据库覆盖即使已经保存和刷新，也不会影响该逻辑。</p><h2 id="增加一个启动设置" tabindex="-1">增加一个启动设置 <a class="header-anchor" href="#增加一个启动设置" aria-label="Permalink to &quot;增加一个启动设置&quot;">​</a></h2><p>以模块本地、重启后生效的设置为例：</p><ol><li>在拥有该行为的设置类中增加带类型和保守默认值的字段。</li><li>若有范围约束，用 Pydantic 字段约束或模块校验函数表达，避免只在调用处临时判断。</li><li>在对应 <code>.env.example</code> 中说明格式和用途，但不要放真实密钥。</li><li>从模块的缓存设置入口读取，不要跨仓库导入另一个服务的设置类。</li><li>增加默认值、环境值、非法值和生产约束测试。</li><li>明确告诉使用者：修改后需要重启哪个进程。</li></ol><p>如果该字段属于 API，就放在 <code>ApiSettings</code>，而不是为了复用已有基类把它塞进 Core。Worker 和 MCP 同理。</p><h2 id="增加一个可在线覆盖设置" tabindex="-1">增加一个可在线覆盖设置 <a class="header-anchor" href="#增加一个可在线覆盖设置" aria-label="Permalink to &quot;增加一个可在线覆盖设置&quot;">​</a></h2><p>除了设置类字段，还要完成一条完整链路：</p><ol><li>在对应运行时定义元组增加 <code>RuntimeSettingDefinition</code>。</li><li>设置稳定的内部 <code>name</code>、大写 <code>env_name</code>、管理分组、值类型和 <code>runtime_note</code>。</li><li>为整数设置最小值、最大值或明确的无限值；为枚举列出选项。</li><li>让服务刷新函数包含这组定义。</li><li>让真正使用该值的代码调用有效设置入口。</li><li>若要在 API 管理页面出现，确认定义进入 <code>MANAGED_RUNTIME_SETTING_DEFINITIONS</code>。</li><li>测试环境值、数据库覆盖、重置、非法输入和生效时机。</li></ol><p>运行时定义当前支持：布尔值、整数、字符串、字符串列表、字符串映射和枚举。通用校验还会：</p><ul><li>拒绝把布尔值当作整数；</li><li>去掉字符串首尾空白，并拒绝空字符串和超过 255 个字符的值；</li><li>清理列表空项，并把列表限制在 50 项；</li><li>把映射键转成小写并排序，最多保留 50 项；</li><li>把枚举值转成小写后与允许选项比较。</li></ul><h3 id="api-所有的运行时设置" tabindex="-1">API 所有的运行时设置 <a class="header-anchor" href="#api-所有的运行时设置" aria-label="Permalink to &quot;API 所有的运行时设置&quot;">​</a></h3><p>在 <code>API_RUNTIME_SETTING_DEFINITIONS</code> 中定义，并加入 <code>ALL_API_RUNTIME_SETTING_DEFINITIONS</code>。API 的刷新函数和系统设置管理服务已经读取这个组合。消费位置必须使用 <code>get_effective_api_settings()</code>。</p><h3 id="core-所有的运行时设置" tabindex="-1">Core 所有的运行时设置 <a class="header-anchor" href="#core-所有的运行时设置" aria-label="Permalink to &quot;Core 所有的运行时设置&quot;">​</a></h3><p>在 <code>CORE_RUNTIME_SETTING_DEFINITIONS</code> 中定义。API 与 Worker 都会读取这组共享定义，因此变更要同时检查两个服务的使用位置和测试。</p><h3 id="worker-所有的运行时设置" tabindex="-1">Worker 所有的运行时设置 <a class="header-anchor" href="#worker-所有的运行时设置" aria-label="Permalink to &quot;Worker 所有的运行时设置&quot;">​</a></h3><p>默认值和管理契约放在 Core 的 <code>worker_runtime_contract.py</code>，对应字段放在 Worker 的 <code>WorkerSettings</code>。API 只保存并展示定义；Worker 自己刷新并通过 <code>get_effective_settings()</code> 使用它们。</p><h2 id="不要把模型通道改回环境变量" tabindex="-1">不要把模型通道改回环境变量 <a class="header-anchor" href="#不要把模型通道改回环境变量" aria-label="Permalink to &quot;不要把模型通道改回环境变量&quot;">​</a></h2><p>模型提供方、地址、密钥、可用模型和用途由 API 管理并存入数据库。当前 <code>.env.example</code> 也明确说明模型通道通过管理接口配置。新增模型能力时应扩展模型通道结构和权限流程，不要添加一组旧式的全局模型环境变量。</p><h2 id="测试什么" tabindex="-1">测试什么 <a class="header-anchor" href="#测试什么" aria-label="Permalink to &quot;测试什么&quot;">​</a></h2><p>至少覆盖：</p><ul><li>默认值与合法环境值能创建设置；</li><li>非法类型、越界值和生产环境危险组合被拒绝；</li><li>数据库覆盖的 <code>source</code> 为 <code>database</code>，重置后回到 <code>environment</code>；</li><li>周期刷新失败后仍会继续下一轮；</li><li>业务消费者确实从有效设置入口读取；</li><li>Worker 契约默认值与 Worker 设置类保持一致；</li><li>密钥或主机列表等安全设置有拒绝路径测试。</li></ul><p>API 仓库当前最接近这条链路的测试是 <code>tests/test_runtime_settings_boundaries.py</code> 和 <code>tests/test_system_settings.py</code>。Core 的共享设置测试在 <code>tests/test_core_settings.py</code> 及运行时设置相关测试中。</p><h2 id="建议执行的检查" tabindex="-1">建议执行的检查 <a class="header-anchor" href="#建议执行的检查" aria-label="Permalink to &quot;建议执行的检查&quot;">​</a></h2><p>在改动所属仓库中使用项目规定的 UV 命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>提交前实际执行这些检查。若改动共享契约，还要在受影响的 API、MCP 或 Worker 仓库分别执行测试和构建。</p><h2 id="完成判据" tabindex="-1">完成判据 <a class="header-anchor" href="#完成判据" aria-label="Permalink to &quot;完成判据&quot;">​</a></h2><ul><li>字段位于实际拥有该行为的模块，没有新增反向依赖。</li><li>环境变量名称、类型、默认值、范围和生产约束都有测试。</li><li>静态设置明确要求重启；在线设置明确说明影响哪些后续操作。</li><li>管理接口显示的值、来源和重置行为与实际消费者一致。</li><li><code>.env.example</code>、类型、测试和文档使用同一名称与含义。</li><li>消费仓库声明了正确的 Core 最低版本与上限，并重新生成锁文件。</li></ul><h2 id="源码位置" tabindex="-1">源码位置 <a class="header-anchor" href="#源码位置" aria-label="Permalink to &quot;源码位置&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>：共享设置和安全校验。</li><li><code>core/src/ershu/services/runtime_settings.py</code>：运行时定义、通用校验、刷新和有效 Core 设置。</li><li><code>core/src/ershu/services/worker_runtime_contract.py</code>：Worker 默认值和管理契约。</li><li><code>api/src/ershu/api/runtime_settings.py</code>：API 设置、校验和有效 API 设置。</li><li><code>api/src/ershu/api/services/system_settings.py</code>：管理员可见定义、数据库写入与重置。</li><li><code>api/src/ershu/api_main.py</code>：API 启动校验和周期刷新。</li><li><code>worker/src/ershu/workers/runtime_settings.py</code>：Worker 字段、校验和有效设置。</li><li><code>mcp/src/ershu/mcp/runtime_settings.py</code>：MCP 字段和生产校验。</li><li><code>api/tests/test_runtime_settings_boundaries.py</code>、<code>api/tests/test_system_settings.py</code>：API 设置边界测试。</li></ul>`,42)])])}const u=i(o,[["render",r]]);export{k as __pageData,u as default};
